import {esc,money} from '../config.mjs';
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',message:'M21 15a3 3 0 0 1-3 3H7l-4 3V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3z',live:'M8 5a8 8 0 0 0 0 14M16 5a8 8 0 0 1 0 14M10 8a4 4 0 0 0 0 8M14 8a4 4 0 0 1 0 8M12 10v4',company:'M4 21V3h12v18M16 11h4v10M8 7h4M8 11h4M8 15h4M2 21h20',video:'M3 4h18v16H3zM10 8l6 4-6 4z',finance:'M3 5h18v14H3zM3 9h18M6 15h3',city:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',team:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'m12 3 10 18H2L12 3zM12 9v5M12 17v1',refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 14-1l1 6M4 12l1 6a8 8 0 0 0 14-1',exit:'M10 4H4v16h6M9 12h12M17 8l4 4-4 4',lab:'M9 3h6M10 3v6l-6 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M8 14h8'};
export const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.message}"/></svg>`;
export const controlNavigation=[['overview','Visão geral','home',''],['all','Mensagens de vídeo','message','OPERAÇÃO'],['community','Comunidade e LIVE','live',''],['sponsors','Patrocinadores','company',''],['episode','Episódios','video',''],['finance','Financeiro','finance','GESTÃO'],['cities','Cidades e ofertas','city',''],['general','Controle geral','settings',''],['trash','Lixeira','trash',''],['administrative','Programação e testes','lab',''],['team','Acesso da equipe','team','']];
export function navigationMarkup(){return `<a class="control-logo" href="/controle/">HOCCO<span>.</span><small>CONTROLE</small></a><nav aria-label="Áreas do controle">${controlNavigation.map(([id,title,i,group])=>(group?`<p class="control-nav-group">${group}</p>`:'')+`<button type="button" data-control-route="${id}">${icon(i)}<span>${title}</span></button>`).join('')}</nav><div class="control-sidebar-bottom"><div class="control-team-avatar">AH</div><div>Equipe HOCCO<small>Acesso autenticado</small></div></div><button class="control-logout" type="button" data-control-logout>${icon('exit')}Sair</button>`}
const paid=r=>r.payment==='confirmed'&&!r.payment_hold;
export const isActiveSponsor=(r,now=Date.now())=>paid(r)&&r.review==='approved'&&!r.archived_at&&Date.parse(r.starts_at)<=now&&Date.parse(r.expires_at)>now;
export const isVisibleCommunity=(r,now=Date.now())=>paid(r)&&r.review==='approved'&&!r.hidden_at&&r.destination!=='live'&&Boolean(r.published_at)&&Date.parse(r.published_at)<=now&&Date.parse(r.expires_at)>now;
export function overviewModel(data,now=Date.now()){
 const video=data.orders||[],community=data.communityMessages||[],sponsors=data.sponsors||[],all=[...video,...community,...sponsors],actions=[];
 const pending=[...video,...community,...sponsors].filter(r=>paid(r)&&r.review==='pending'&&!r.hidden_at&&!r.archived_at);
 const activeSponsors=sponsors.filter(r=>isActiveSponsor(r,now));
 const attention=all.filter(r=>r.payment_hold||(r.payment==='confirmed'&&r.review==='rejected'));
 for(const [rows,type,route,label] of [[sponsors,'Empresas','sponsors','Empresa aguardando análise'],[video,'Vídeo','review','Mensagem para vídeo'],[community,'Comunidade','community','Mensagem para revisão']])for(const r of rows.filter(r=>paid(r)&&r.review==='pending'&&!r.hidden_at&&!r.archived_at))actions.push({id:r.id,type,route,title:label,detail:route==='sponsors'?(r.company_name||r.code):r.code,status:'Pago',tone:'success',button:route==='sponsors'?'Revisar empresa':'Analisar'});
 for(const r of attention)actions.push({id:r.id,type:sponsors.includes(r)?'Empresas':video.includes(r)?'Vídeo':'Comunidade',route:sponsors.includes(r)?'sponsors':video.includes(r)?'all':'community',title:'Pedido precisa de conferência',detail:r.code,status:r.payment_hold?'Pagamento em atenção':'Recusado · pago',tone:'orange',button:'Abrir pedido'});
 for(const r of activeSponsors.filter(r=>Date.parse(r.expires_at)-now<=86400000))actions.push({id:r.id,type:'Empresas',route:'sponsors',title:'Patrocínio próximo do vencimento',detail:r.company_name||r.code,status:'Até 24h',tone:'orange',button:'Ver patrocínio'});
 return{pending:pending.length,payments:all.filter(r=>r.payment==='pending').length,activeSponsors:activeSponsors.length,live:community.filter(r=>paid(r)&&r.review==='approved'&&!r.hidden_at&&r.destination==='live'&&r.live_status==='queued').length,attention:attention.length,actions,activity:(data.audit||[]).slice().sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at)).slice(0,5),limited:[video,community,sponsors].some(rows=>rows.length>=500)};
}
const actionTitle=a=>({featured_episode_update:'Episódio atualizado',general_control_update:'Controles gerais atualizados',community_pricing:'Preço da Comunidade atualizado',settings:'Configuração atualizada',approve:'Mensagem aprovada',publish:'Veiculação registrada',pay:'Pagamento confirmado',refund:'Devolução registrada',edit:'Mensagem editada'}[a]||'Alteração registrada');
export function overviewMarkup(data,{now=Date.now(),category='Todas'}={}){
 const m=overviewModel(data,now),s=data.settings||{},actions=m.actions.filter(a=>category==='Todas'||a.type===category).slice(0,8);
 return `<section class="control-overview"><div class="control-page-head"><div><h1>Visão geral</h1><p>Acompanhe a operação e resolva o que precisa de atenção.</p></div><span class="control-updated">Consulta: ${esc(new Date(now).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}</span><button class="btn secondary" data-control-refresh>${icon('refresh')}Atualizar</button></div><div class="control-summary-grid">${[['Curadoria pendente',m.pending,'Pagamentos confirmados','message'],['Pagamentos pendentes',m.payments,'Aguardando confirmação','finance'],['Patrocínios ativos',m.activeSponsors,'Em exibição','company'],['Fila da LIVE',m.live,'Aguardando leitura','live']].map(([t,n,d,i])=>`<article class="control-summary-card"><span class="control-metric-icon">${icon(i)}</span><div><h2>${t}</h2><strong>${n}</strong><p>${d}</p></div></article>`).join('')}</div>${m.limited?'<p class="control-scope-note">Indicadores desta consulta: até 500 registros recentes de cada modalidade. O histórico completo continua no banco.</p>':''}${m.attention?`<div class="control-attention">${icon('alert')}<strong>${m.attention} solicitação(ões) precisam de conferência.</strong><button class="btn secondary small" data-control-route="finance">Ver financeiro</button></div>`:''}<div class="control-overview-grid"><section class="control-panel control-actions-panel"><div class="control-panel-heading"><h2>Próximas ações</h2><div class="control-filter-pills" role="group" aria-label="Filtrar próximas ações">${['Todas','Vídeo','Comunidade','Empresas'].map(c=>`<button type="button" data-overview-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div></div><div class="control-action-list">${actions.map(a=>`<article class="control-action-row"><span class="control-row-icon">${icon(a.type==='Empresas'?'company':'message')}</span><div class="control-action-copy"><h3>${esc(a.title)}</h3><p>${esc(a.detail||'Solicitação registrada')}</p></div><span class="badge ${a.tone}">${esc(a.status)}</span><button class="btn secondary small" data-control-route="${a.route}" data-control-record="${esc(a.id)}">${a.button}</button></article>`).join('')||'<div class="control-empty"><h3>Nenhuma ação pendente nesta seleção.</h3><p>As solicitações que exigirem sua atenção aparecerão aqui.</p></div>'}</div><button class="control-text-link" data-control-route="all">Ver mensagens de vídeo ${icon('video')}</button></section><aside class="control-overview-side"><section class="control-panel control-episode-panel"><h2>Episódio em destaque</h2><img src="/assets/cinema/school.webp" alt="Imagem ilustrativa da série HOCCO"><h3>${esc(s.featured_episode_title||'Nenhum episódio definido')}</h3><p>${s.featured_episode_title?'Título e link exibidos na aba Episódios do cliente.':'Cadastre o nome e o link do vídeo publicado.'}</p><button class="btn" data-control-route="episode">Definir episódio</button></section><section class="control-panel"><h2>Ações rápidas</h2><div class="control-quick-grid">${[['general','Alterar preços','settings','general-video-price-1'],['general','Mensagem oficial','message','founder-notice'],['administrative','Programar LIVE','live','program-topic'],['administrative','Abrir laboratório','lab','open-laboratory']].map(([r,t,i,target])=>`<button class="btn secondary" data-control-route="${r}" data-control-focus="${target}">${icon(i)}${t}</button>`).join('')}</div></section></aside></div><div class="control-lower-grid"><section class="control-panel"><h2>Atividade recente</h2><ol class="control-activity">${m.activity.map(a=>`<li>${icon('clock')}<div><strong>${esc(actionTitle(a.action))}</strong><small>${esc(new Date(a.created_at).toLocaleString('pt-BR'))}</small></div></li>`).join('')||'<li>Nenhuma alteração disponível nesta consulta.</li>'}</ol></section><section class="control-panel"><h2>Conferência da operação</h2><p class="hint">Estados dos registros consultados. Esta tela não mede a disponibilidade contínua dos serviços.</p><div class="control-health-row"><span>Pagamento</span><strong>Verificado no servidor</strong></div><div class="control-health-row"><span>Curadoria</span><strong>${m.pending} pendente(s)</strong></div><div class="control-health-row"><span>Divergências</span><strong>${m.attention} em atenção</strong></div><button class="control-text-link" data-control-route="recovery">Abrir recuperação financeira ${icon('finance')}</button></section></div><p class="control-scope-note">Dados da última consulta. Atualize para receber novos pedidos e alterações. As ações preservam o histórico dos registros.</p></section>`;
}
